   const stripes=Array.from({length:100},(_,i)=>{const a=i<50?'low':'middle',b=i<50?'middle':'high',mix=Math.round((i<50?i/49:(i-50)/49)*100),fill=i<v.value?`color-mix(in srgb, ${F.v('component.metric.'+a)} ${100-mix}%, ${F.v('component.metric.'+b)} ${mix}%)`:F.v('component.metric.track');return `<rect x="${i*(width+gap)}" y="0" width="${width}" height="${height}" rx="${radius}" fill="${fill}"/>`;}).join('');
   return `<section class="pp-detail-block pp-metric-card score"><header class="pp-metric-score-head"><div><h3>Overall score</h3><p class="pp-detail-meta">Company assessment</p></div><div class="pp-metric-score-value"><strong>${v.value}</strong><span class="pp-detail-meta">out of 100</span></div></header><svg class="pp-metric-stripes" viewBox="0 0 ${100*(width+gap)} ${height}" preserveAspectRatio="none" role="meter" aria-label="Overall score" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${v.value}" aria-valuetext="${v.value} out of 100"><title>Overall score: ${v.value} out of 100</title>${stripes}</svg>${v.footer?`<footer class="pp-metric-score-footer"><span class="pp-detail-meta">Current assessment</span>${F.badge({tone,size:'sm'},quality)}</footer>`:''}</section>`;
