 const histories={experience:[['Product lead','Northstar','2023 – Present','Leads product strategy and a cross-functional delivery team.'],['Senior designer','Fieldwork','2020 – 2023','Built shared product patterns and improved core customer workflows.'],['Product designer','Studio One','2017 – 2020','Designed and shipped tools for growing teams.']],education:[['MSc, Human–Computer Interaction','City University','2015 – 2017','Research focused on collaborative interfaces.'],['BSc, Computer Science','State University','2011 – 2015','Studied software systems and interaction design.']]};
